//! Golden fixtures for #13623: the presenter pipeline against a bounded,
//! test-owned image and its icat/chafa reference output.
//!
//! Fixture provenance (see `fixtures/README.md`): `gradient-16x8.png` is a
//! 16x8 RGB gradient (red rising left to right, `G=0 B=128`), generated by a
//! checked-in Python script with only the stdlib. `chafa-16x8-red-gradient`
//! is the headless `chafa 1.18.3` rendering of that PNG at `-s 16x8`. The
//! pipeline never shells out to either tool; the files pin what the
//! reference renderers show for the same input so regressions are visible.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::num::NonZeroU32;

use id_worlds::kitty_graphics::{Action, GraphicsGate, PayloadClass};
use id_worlds::kitty_still::{prepare_still, CellBudget};

/// The bounded test-owned fixture: 16x8, 120 bytes, well under every cap.
const FIXTURE_PNG: &[u8] = include_bytes!("fixtures/gradient-16x8.png");

/// Headless `chafa -s 16x8` rendering of the same PNG.
const CHAFA_REFERENCE: &str = include_str!("fixtures/chafa-16x8-red-gradient.symbols");

/// A gate that accepted exactly the PNG class.
fn png_gate() -> GraphicsGate {
    let mut gate = GraphicsGate::new(true);
    for class in PayloadClass::ALL {
        gate.record_answer(class, class == PayloadClass::Png);
    }
    gate
}

/// The 16x8 fixture fits a 16x8 cell area at 1px cells exactly, so the
/// front half must pass its bytes through untouched and the encoder must
/// emit one quiet direct PNG transmission for it.
#[test]
fn still_passthrough_matches_reference_geometry() {
    let budget = CellBudget {
        columns: 16,
        rows: 8,
        cell_px: Some((1, 1)),
    };
    let gate = png_gate();
    let still = prepare_still(FIXTURE_PNG, budget, &gate)
        .expect("fixture is a bounded valid PNG")
        .expect("a PNG-accepting session gets a still");
    assert_eq!((still.width(), still.height()), (16, 8));
    assert_eq!((still.columns(), still.rows()), (16, 8));
    assert!(
        still.is_passthrough(),
        "an exactly-fitting PNG must pass through untouched"
    );

    let image_id = NonZeroU32::new(7).unwrap();
    let placement = still.placement();
    let out = gate
        .encode_still(image_id, still.payload(), Action::Place(placement))
        .expect("passthrough payload encodes")
        .expect("PNG gate is open");
    assert!(
        out.starts_with("\x1b_Ga=T,f=100,t=d,i=7"),
        "direct PNG placement under image ID 7, got {out:?}"
    );
    assert!(
        out.contains(",q=2,m=0;"),
        "a 120-byte PNG is one quiet final chunk, got {out:?}"
    );
    assert_eq!(
        out.matches("\x1b_G").count(),
        1,
        "single-chunk transmission emits one APC opener"
    );
    let payload_b64 = out.split(';').next_back().unwrap_or_default();
    let payload_b64 = payload_b64.trim_end_matches("\x1b\\");
    assert!(!payload_b64.is_empty(), "transmission carries a payload");
}

/// The checked-in chafa output for the same PNG shows the same gradient:
/// four half-block rows of sixteen cells, red rising left to right on both
/// the foreground (even pixels) and background (odd pixels) of every row.
#[test]
fn chafa_reference_shows_same_gradient() {
    let rows: Vec<&str> = CHAFA_REFERENCE
        .lines()
        .filter(|line| line.contains('▌'))
        .collect();
    assert_eq!(rows.len(), 4, "8 pixel rows render as 4 half-block rows");

    let reds = |line: &str, key: &str| -> Vec<u8> {
        line.split(key)
            .skip(1)
            .filter_map(|tail| tail.split(';').next())
            .filter_map(|n| n.parse::<u8>().ok())
            .collect()
    };
    let first_fg = reds(rows[0], "38;2;");
    assert_eq!(first_fg.len(), 16, "one foreground cell per column");
    assert!(
        first_fg.windows(2).all(|w| w[1] >= w[0]),
        "chafa foreground reds rise left to right: {first_fg:?}"
    );
    assert!(
        first_fg[0] < 16 && *first_fg.last().unwrap_or(&0) > 230,
        "gradient spans dark-to-bright red: {first_fg:?}"
    );

    for (index, row) in rows.iter().enumerate() {
        assert_eq!(
            reds(row, "38;2;"),
            first_fg,
            "row {index} repeats the gradient"
        );
        let bg = reds(row, "48;2;");
        assert_eq!(bg.len(), 16, "one background cell per column");
        assert!(
            bg.windows(2).all(|w| w[1] >= w[0]),
            "row {index} background reds rise too: {bg:?}"
        );
        assert!(
            bg.iter()
                .zip(first_fg.iter())
                .all(|(b, f)| *b > *f && *b - *f < 32),
            "row {index} pairs adjacent gradient pixels: {bg:?}"
        );
    }
}
